package com.lexorion.workforce.domain;
import com.lexorion.workforce.config.Auditable;import jakarta.persistence.*;import java.time.LocalDate;import java.util.UUID;import lombok.*;import org.hibernate.annotations.UuidGenerator;
@Entity @Table(name="employees",uniqueConstraints={@UniqueConstraint(name="uk_employee_workspace_code",columnNames={"workspace_id","employee_code"}),@UniqueConstraint(name="uk_employee_workspace_platform_user",columnNames={"workspace_id","platform_user_id"})},indexes={@Index(name="idx_employee_workspace",columnList="workspace_id"),@Index(name="idx_employee_status",columnList="employment_status")}) @Getter @Setter @NoArgsConstructor
public class Employee extends Auditable {@Id @UuidGenerator private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="workspace_id",nullable=false,updatable=false)private WorkforceWorkspace workspace;@Column(name="platform_user_id")private UUID platformUserId;@Column(name="employee_code",nullable=false,length=63,updatable=false)private String code;@Column(nullable=false,length=100)private String firstName;@Column(length=100)private String middleName;@Column(nullable=false,length=100)private String lastName;@Column(nullable=false,length=254)private String workEmail;@Column(length=30)private String phone;@Column(nullable=false)private LocalDate joiningDate;@Enumerated(EnumType.STRING)@Column(name="employment_status",nullable=false,length=20)private EmploymentStatus status=EmploymentStatus.ACTIVE;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="department_id")private Department department;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="designation_id")private Designation designation;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="reporting_manager_id")private Employee reportingManager;}
